//! The CI workflow, generated by xtask, and the gate that holds the file to it.

use crate::{
    parts::{Part, SHARD_REPORTS, UNVIABLE_ARTIFACT},
    preflight::{NODE_FLOOR, PINNED_TOOLS, node_release, supported},
    steps::{Failure, step_verdict},
    workspace::{
        COVERAGE_DIR, CargoWorkspace, NIGHTLY_TOOLCHAIN, PACKAGES, UNVIABLE_REPORT,
        typescript_reports,
    },
};

/// The CI workflow.
pub const WORKFLOW: &str = ".github/workflows/quality.yml";

/// The Node.js release CI uses, pinned.
pub const NODE_VERSION_FILE: &str = ".node-version";

/// The snapshot of Ubuntu's archive the CI jobs install their system packages from, a
/// timestamp of <https://snapshot.ubuntu.com>: a macro, so that the source line of
/// [`AUDIO_SINK`] is one constant built from it. Moving it to a later instant is how a
/// pinned package moves to a newer version.
macro_rules! apt_snapshot {
    () => {
        "20261115T000000Z"
    };
}

/// The WebAssembly modules the packages build, uploaded by a failed CI run.
///
/// One glob over every package's `dist/` ([`WASM_PACKAGES`](crate::WASM_PACKAGES)), so
/// that a package that comes to build a module is uploaded with no change here; their
/// bytes can then be compared with a local build.
pub const WASM_MODULES: &str = "bindings/*/dist/*.wasm";

/// What Playwright leaves in a package after its browser tests: its report, and the traces
/// and screenshots of the failed tests.
pub const PLAYWRIGHT_OUTPUTS: [&str; 2] = ["playwright-report", "test-results"];

/// What a failed CI run uploads.
///
/// Every report a gate of xtask reads (the mutants, the Rust coverage, the coverage and
/// mutation reports of every TypeScript package, as one glob per folder of parts), the
/// WebAssembly modules, then Playwright's outputs ([`PLAYWRIGHT_OUTPUTS`]) of every folder
/// of parts.
#[must_use]
pub fn failure_uploads() -> Vec<String> {
    let mut uploads: Vec<String> = [
        UNVIABLE_REPORT.split('/').next().unwrap_or(UNVIABLE_REPORT),
        COVERAGE_DIR,
    ]
    .into_iter()
    .chain([WASM_MODULES])
    .map(str::to_owned)
    .collect();
    for report in typescript_reports() {
        // `<folder>/<package>/<kind>[/…]` becomes `<folder>/*/<kind>`.
        let mut parts = report.split('/');
        let folder = parts.next().unwrap_or_default();
        let glob = format!("{folder}/*/{}", parts.nth(1).unwrap_or_default());
        if !uploads.contains(&glob) {
            uploads.push(glob);
        }
    }
    for package in PACKAGES {
        let folder = package.dir.split('/').next().unwrap_or_default();
        for output in PLAYWRIGHT_OUTPUTS {
            let glob = format!("{folder}/*/{output}");
            if !uploads.contains(&glob) {
                uploads.push(glob);
            }
        }
    }
    uploads
}

/// The exact triggers of the workflow: every push, every pull request, and by hand, with
/// the parts to check given as text (empty for every part, [`ci_parts`](crate::commits::ci_parts)).
pub const WORKFLOW_TRIGGERS: [&str; 9] = [
    "on:",
    "  push:",
    "  pull_request:",
    "  workflow_dispatch:",
    "    inputs:",
    "      parts:",
    "        description: The parts to check, separated by spaces (cargo xtask list --full --parts, final apart); empty for every part",
    "        type: string",
    "        default: ''",
];

/// The exact permissions of the workflow's token: reading the repository.
pub const WORKFLOW_PERMISSIONS: [&str; 2] = ["permissions:", "  contents: read"];

/// The commands that give each job of the check's matrix an audio output, in this order:
/// every part but the final one, which plays nothing.
///
/// The runner has no sound card, and Firefox plays live only through an audio server
/// (Chromium runs with its audio output disabled, and Playwright's `WebKit` on Linux plays
/// without one): without it, every live test of the engine package and of the playground
/// fails in Firefox alone. The `pulseaudio` server, which the runner's image does not
/// hold, is installed at an exact version without its recommended packages, from the
/// fixed snapshot of the OS release's updates the first line adds to the package sources
/// (`apt_snapshot!`): the updates pocket keeps only its newest version, so a version
/// pinned there alone stops installing at the next Ubuntu update, while the snapshot keeps
/// it. A package pinned is not its closure: pulseaudio depends on `libpulse0` at its own
/// exact version, which apt would take newer from the live archive, or keep newer from the
/// image. So the second line prefers the snapshot over every other source (an apt
/// preference of priority 1001, above which apt also downgrades), and each install allows
/// the downgrade: every package an install brings in comes from the snapshot. Playwright's
/// `--with-deps`, run before, installs the browsers' system libraries from the live
/// archive, on which no bit-exact output depends. The server is then started for the
/// whole job with a null sink as the default output, and the last line fails the step,
/// with one line naming the cause, unless that sink is the default.
pub const AUDIO_SINK: [&str; 8] = [
    concat!(
        "echo 'deb https://snapshot.ubuntu.com/ubuntu/",
        apt_snapshot!(),
        " noble-updates main universe' | sudo tee /etc/apt/sources.list.d/snapshot.list >/dev/null"
    ),
    "printf 'Package: *\\nPin: origin \"snapshot.ubuntu.com\"\\nPin-Priority: 1001\\n' | sudo tee /etc/apt/preferences.d/snapshot >/dev/null",
    "sudo apt-get update",
    "sudo apt-get install --yes --no-install-recommends --allow-downgrades pulseaudio=1:16.1+dfsg1-2ubuntu10.1",
    "pulseaudio --start --exit-idle-time=-1",
    "pactl load-module module-null-sink sink_name=null",
    "pactl set-default-sink null",
    "pactl get-default-sink | grep --quiet --line-regexp null || { echo \"::error::no audio sink: Firefox cannot play live (the runner has no sound card)\"; exit 1; }",
];

/// The commands that give each job of the check's matrix a software GPU, in this order.
///
/// Lavapipe, Mesa's Vulkan driver on the processor, which the GPU workspace's tests,
/// coverage and mutants render on (the runner has no GPU).
///
/// Installed at an exact version without its recommended packages, from the snapshot
/// [`AUDIO_SINK`] adds to the package sources and prefers over every other, its
/// dependencies with it (downgrades allowed), after the package lists it updates; the
/// last line fails the step, with one line naming the cause, unless lavapipe's Vulkan
/// driver is declared to the loader.
pub const SOFTWARE_GPU: [&str; 2] = [
    "sudo apt-get install --yes --no-install-recommends --allow-downgrades mesa-vulkan-drivers=25.2.8-0ubuntu0.24.04.4",
    "ls /usr/share/vulkan/icd.d/lvp_icd.*.json >/dev/null || { echo \"::error::no software GPU: lavapipe's Vulkan driver is not declared (the GPU workspace's tests need it)\"; exit 1; }",
];

/// The only conditions the workflow may hold, exactly.
///
/// The upload of the reports after a failure; the maintainer's decision that a push runs
/// the check only when its last commit asks for it with a marker, `[ci]` or `[ci <part>…]`
/// (pull requests and manual runs always run it), held by the job reading the parts; a
/// check only of the parts it read, if any; and the final part only after every part
/// (`full`, [`ci_outputs`](crate::commits::ci_outputs)), so that a run of some parts is never a full check. Any other
/// condition, or a variant of these, could skip the check without anyone deciding it.
pub const WORKFLOW_CONDITIONS: [&str; 4] = [
    "if: failure()",
    "if: github.event_name != 'push' || contains(github.event.head_commit.message, '[ci]') || contains(github.event.head_commit.message, '[ci ')",
    "if: needs.parts.outputs.parts != '[]'",
    "if: needs.parts.outputs.full == 'true'",
];

/// The exact concurrency of the workflow.
///
/// A newer run of the check cancels the older one of the same ref, while a run that the
/// `[ci]` condition of [`WORKFLOW_CONDITIONS`] skips gets a group of its own, so that it
/// never cancels a check in progress and then skips its own.
#[must_use]
pub fn workflow_concurrency() -> [String; 3] {
    let [_, condition, ..] = WORKFLOW_CONDITIONS;
    let condition = condition.strip_prefix("if: ").unwrap_or(condition);
    [
        "concurrency:".to_owned(),
        format!(
            "  group: ${{{{ ({condition}) && format('quality-{{0}}', github.ref) || format('skipped-{{0}}', github.run_id) }}}}"
        ),
        "  cancel-in-progress: true".to_owned(),
    ]
}

/// The release of the OS every job of the workflow runs on.
///
/// Never `-latest`, which moves to a new release without a commit. The runner image itself
/// still receives GitHub's weekly updates, which no workflow can pin.
pub const RUNNER: &str = "ubuntu-24.04";

/// The timeout of the job reading the parts, of each job of the check's matrix, then of
/// the final job, in minutes.
///
/// A guard against a hung job. The matrix's is temporarily wide, above the slowest measured
/// run of its longest part (the oracle's mutation testing), until that part is split.
pub const JOB_TIMEOUTS: [u32; 3] = [15, 300, 30];

/// The timeout of the Miri part's job ([`Part::Miri`]), in minutes, below the matrix's.
///
/// Miri runs only the tests of the crates holding `unsafe` code, which hold only their
/// boundary: the job took 6 minutes on `main`'s run of 2026-11-15, its setup included. A
/// test that renders under Miri at length (seconds per block) makes the job fail at this
/// bound instead of passing hours later, unseen in the matrix's wide timeout.
pub const MIRI_TIMEOUT: u32 = 30;

/// The components of the [`NIGHTLY_TOOLCHAIN`]: branch coverage and Miri.
pub const NIGHTLY_COMPONENTS: [&str; 3] = ["llvm-tools-preview", "miri", "rust-src"];

/// The steps that install the tools of a job: the checkout (the whole history, for the
/// history gate, and no credential kept), the model of the runner's processor (`lscpu`, so
/// that a slow run is explained by its log: hosted runners differ), the pinned toolchains,
/// the Rust cache (`keyed`
/// by the part, for the check's matrix, and saved even when the run fails), the Cargo tools
/// of [`PINNED_TOOLS`], pnpm and Node.js (its packages cached, for the check's matrix).
pub(crate) fn tool_steps(keyed: bool) -> Vec<String> {
    let nightly = NIGHTLY_TOOLCHAIN.trim_start_matches('+');
    let tools = PINNED_TOOLS
        .iter()
        .map(|(name, version)| format!("{name}@{version}"))
        .collect::<Vec<_>>()
        .join(",");
    let mut steps = vec![
        "      - uses: actions/checkout@".to_owned(),
        "        with:".to_owned(),
        "          fetch-depth: 0".to_owned(),
        "          persist-credentials: false".to_owned(),
        "      - name: The runner's processor".to_owned(),
        "        run: lscpu".to_owned(),
        "      - name: Install Rust toolchains".to_owned(),
        "        run: |".to_owned(),
        "          rustup toolchain install".to_owned(),
        format!(
            "          rustup toolchain install {nightly} --profile minimal --component {}",
            NIGHTLY_COMPONENTS.join(",")
        ),
        "      - uses: Swatinem/rust-cache@".to_owned(),
        "        with:".to_owned(),
    ];
    if keyed {
        // Every Cargo workspace's target directory, each part building the GPU workspace's
        // too.
        steps.push("          key: ${{ matrix.part }}".to_owned());
        steps.push("          workspaces: |".to_owned());
        steps.extend(
            CargoWorkspace::ALL
                .map(|workspace| format!("            {} -> target", workspace.dir())),
        );
    }
    steps.extend([
        "          cache-on-failure: true".to_owned(),
        "      - uses: taiki-e/install-action@".to_owned(),
        "        with:".to_owned(),
        format!("          tool: {tools}"),
        "      - uses: pnpm/action-setup@".to_owned(),
        "      - uses: actions/setup-node@".to_owned(),
        "        with:".to_owned(),
        format!("          node-version-file: {NODE_VERSION_FILE}"),
    ]);
    if keyed {
        steps.push("          cache: pnpm".to_owned());
    }
    steps
}

/// The workflow's first job, `parts`, held by the marker condition `ci` and stopped after
/// `timeout` minutes: it reads the parts to check ([`ci_parts`](crate::commits::ci_parts)) into its outputs.
pub(crate) fn parts_job(ci: &str, timeout: u32) -> Vec<String> {
    vec![
        "  parts:".to_owned(),
        "    name: The parts to check".to_owned(),
        format!("    {ci}"),
        format!("    runs-on: {RUNNER}"),
        format!("    timeout-minutes: {timeout}"),
        "    outputs:".to_owned(),
        "      parts: ${{ steps.parts.outputs.parts }}".to_owned(),
        "      full: ${{ steps.parts.outputs.full }}".to_owned(),
        "    steps:".to_owned(),
        "      - uses: actions/checkout@".to_owned(),
        "        with:".to_owned(),
        "          persist-credentials: false".to_owned(),
        "      - name: Install the Rust toolchain".to_owned(),
        "        run: rustup toolchain install".to_owned(),
        "      - uses: Swatinem/rust-cache@".to_owned(),
        "        with:".to_owned(),
        "          key: parts".to_owned(),
        "          cache-on-failure: true".to_owned(),
        "      - name: The parts asked for".to_owned(),
        "        id: parts".to_owned(),
        "        env:".to_owned(),
        "          EVENT: ${{ github.event_name }}".to_owned(),
        "          MESSAGE: ${{ github.event.head_commit.message }}".to_owned(),
        "          PARTS: ${{ inputs.parts }}".to_owned(),
        "        run: cargo xtask ci-parts \"$EVENT\" \"$MESSAGE\" \"$PARTS\" >> \"$GITHUB_OUTPUT\"".to_owned(),
    ]
}

/// The one workflow CI may run, line by line, without its comments and blank lines: each
/// line using an action ends with `@`, where the workflow pins a full commit hash
/// ([`workflow_gate`]).
///
/// Built from what xtask owns: the triggers, the token's permissions and the concurrency
/// ([`WORKFLOW_TRIGGERS`], [`WORKFLOW_PERMISSIONS`], [`workflow_concurrency`]), the
/// conditions ([`WORKFLOW_CONDITIONS`]), the [`RUNNER`] and the [`JOB_TIMEOUTS`], the tools
/// (the checkout, the toolchains with [`NIGHTLY_COMPONENTS`], the Rust cache,
/// [`PINNED_TOOLS`], pnpm and Node.js). A job `parts`, run only when asked (the marker
/// condition), reads the parts to check with `cargo xtask ci-parts` ([`ci_parts`](crate::commits::ci_parts)), the
/// commit message and the parts given by hand passed through the environment, never
/// written into the script. A job `check` runs those parts, one per job of its matrix and
/// all of them whatever fails (every part of [`matrix_parts`](crate::commits::matrix_parts) for a full check), after the
/// browsers and the audio output ([`AUDIO_SINK`]) its live tests need, and the software
/// GPU ([`SOFTWARE_GPU`]) its GPU tests need; each uploads the
/// unviable mutants of its shard, if it ran one, as the artifact `unviable-<part>`
/// ([`UNVIABLE_ARTIFACT`]), and, when it failed, every report ([`failure_uploads`]). The
/// job `final` runs only when every part ran, needs every one, downloads their unviable
/// mutants below [`SHARD_REPORTS`] and runs the final part, which reviews them together:
/// so a run of some parts never has a final job, and is never a full check.
#[must_use]
pub fn workflow_text() -> Vec<String> {
    let [failure, ci, some, every] = WORKFLOW_CONDITIONS;
    let [parts_timeout, check_timeout, final_timeout] = JOB_TIMEOUTS;
    let each = "${{ matrix.part }}";
    let mut lines = vec!["name: Quality".to_owned()];
    lines.extend(WORKFLOW_TRIGGERS.map(str::to_owned));
    lines.extend(WORKFLOW_PERMISSIONS.map(str::to_owned));
    lines.extend(workflow_concurrency());
    lines.push("jobs:".to_owned());
    lines.extend(parts_job(ci, parts_timeout));
    lines.extend([
        "  check:".to_owned(),
        format!("    name: {each}"),
        "    needs: parts".to_owned(),
        format!("    {some}"),
        format!("    runs-on: {RUNNER}"),
        format!(
            "    timeout-minutes: ${{{{ matrix.part == '{}' && {MIRI_TIMEOUT} || {check_timeout} }}}}",
            Part::Miri.name()
        ),
        "    strategy:".to_owned(),
        "      fail-fast: false".to_owned(),
        "      matrix:".to_owned(),
        "        part: ${{ fromJSON(needs.parts.outputs.parts) }}".to_owned(),
        "    steps:".to_owned(),
    ]);
    lines.extend(tool_steps(true));
    lines.extend([
        "      - name: Install Playwright browsers".to_owned(),
        "        run: |".to_owned(),
        "          pnpm install --frozen-lockfile".to_owned(),
        "          pnpm --dir apps/roadmap exec playwright install --with-deps chromium firefox \
         webkit"
            .to_owned(),
        "      - name: Start an audio server with a null sink".to_owned(),
        "        run: |".to_owned(),
    ]);
    lines.extend(AUDIO_SINK.map(|line| format!("          {line}")));
    lines.extend([
        "      - name: Install a software GPU (lavapipe)".to_owned(),
        "        run: |".to_owned(),
    ]);
    lines.extend(SOFTWARE_GPU.map(|line| format!("          {line}")));
    lines.extend([
        format!("      - name: cargo xtask check --full --part {each}"),
        format!("        run: cargo xtask check --full --part {each}"),
        "      - uses: actions/upload-artifact@".to_owned(),
        "        with:".to_owned(),
        format!("          name: {UNVIABLE_ARTIFACT}{each}"),
        format!("          path: {UNVIABLE_REPORT}"),
        "          if-no-files-found: ignore".to_owned(),
        "      - uses: actions/upload-artifact@".to_owned(),
        format!("        {failure}"),
        "        with:".to_owned(),
        format!("          name: reports-{each}"),
        "          path: |".to_owned(),
    ]);
    lines.extend(
        failure_uploads()
            .into_iter()
            .map(|path| format!("            {path}")),
    );
    lines.extend([
        "          if-no-files-found: ignore".to_owned(),
        "  final:".to_owned(),
        format!("    name: {}", Part::Final.name()),
        "    needs: [parts, check]".to_owned(),
        format!("    {every}"),
        format!("    runs-on: {RUNNER}"),
        format!("    timeout-minutes: {final_timeout}"),
        "    steps:".to_owned(),
    ]);
    lines.extend(tool_steps(false));
    lines.extend([
        "      - uses: actions/download-artifact@".to_owned(),
        "        with:".to_owned(),
        format!("          pattern: {UNVIABLE_ARTIFACT}*"),
        format!("          path: {SHARD_REPORTS}"),
        format!(
            "      - name: cargo xtask check --full --part {}",
            Part::Final.name()
        ),
        format!(
            "        run: cargo xtask check --full --part {}",
            Part::Final.name()
        ),
    ]);
    lines
}

/// Whether `found`, a line of the workflow, is `expected`, a line of [`workflow_text`]: the
/// same text, but that a line using an action (ending with `@`) is followed by a full
/// commit hash in lowercase, then nothing or a comment naming its tag (` # <tag>`, as
/// Dependabot writes it).
pub(crate) fn workflow_line(expected: &str, found: &str) -> bool {
    if !expected.ends_with('@') {
        return found == expected;
    }
    found
        .strip_prefix(expected)
        .and_then(|reference| reference.split_at_checked(40))
        .is_some_and(|(commit, tag)| {
            commit
                .bytes()
                .all(|byte| matches!(byte, b'0'..=b'9' | b'a'..=b'f'))
                && (tag.is_empty()
                    || tag
                        .strip_prefix(" # ")
                        .is_some_and(|tag| !tag.trim().is_empty()))
        })
}

/// The first line where `workflow` is not [`workflow_text`], said with its number, if
/// there is one: its blank lines and the lines holding only a comment apart, which execute
/// nothing (a `#` line of a `run` block is a comment of the shell).
pub(crate) fn workflow_difference(workflow: &str) -> Option<String> {
    if !workflow.ends_with('\n') {
        return Some(format!("{WORKFLOW} does not end with a line break"));
    }
    let shown = |expected: &str| {
        if expected.ends_with('@') {
            format!("{expected}<full commit hash> # <tag>")
        } else {
            expected.to_owned()
        }
    };
    let mut found = workflow.lines().zip(1_usize..).filter(|(line, _)| {
        let text = line.trim_start();
        !text.is_empty() && !text.starts_with('#')
    });
    for expected in workflow_text() {
        let Some((line, number)) = found.next() else {
            return Some(format!(
                "{WORKFLOW} ends where xtask's workflow goes on with `{}`",
                shown(&expected)
            ));
        };
        if !workflow_line(&expected, line) {
            return Some(format!(
                "{WORKFLOW}:{number}: `{line}`, where xtask's workflow has `{}`",
                shown(&expected)
            ));
        }
    }
    found.next().map(|(line, number)| {
        format!("{WORKFLOW}:{number}: `{line}`, after the end of xtask's workflow")
    })
}

/// Checks that CI runs exactly the workflow xtask defines, so that it can neither change
/// without a commit to xtask nor pass without checking.
///
/// `workflows` are the workflow files tracked by git: only [`WORKFLOW`]. Its lines, its
/// blank lines and comment lines apart, are those of [`workflow_text`], in order, each
/// action pinned to a full commit hash in lowercase, then nothing or ` # <tag>`; so every
/// setting is xtask's, and any other (a default shell, a condition, a step, a runner, a
/// credential kept) is refused. `.node-version` pins one Node.js release, [`NODE_FLOOR`] or
/// later.
///
/// Outside the gate's scope, written only on purpose (`CLAUDE.md`, "A gate guards against
/// honest mistakes"): comment lines are told by `lines()`, which breaks at a line feed only
/// (a carriage return before it included), so a line break YAML may read elsewhere inside a
/// comment (a lone carriage return, NEL, a line or paragraph separator) is not seen; and
/// which commit a pinned hash names is Dependabot's and the reviewer's, so a hash of a
/// commit outside the action's own repository (a fork's) is not seen either.
///
/// # Errors
///
/// Returns every other workflow, the first line where the workflow differs from xtask's,
/// and a loose Node.js release.
pub fn workflow_gate(
    workflows: &[String],
    workflow: &str,
    node_version: &str,
) -> Result<(), Failure> {
    let mut problems: Vec<String> = workflows
        .iter()
        .filter(|path| *path != WORKFLOW)
        .map(|path| format!("{path}: the only workflow is {WORKFLOW}, which xtask checks"))
        .collect();
    problems.extend(workflow_difference(workflow));
    if !node_release(node_version).is_some_and(supported) {
        problems.push(format!(
            "{NODE_VERSION_FILE} must pin one Node.js release, {}.{} or later (X.Y.Z): found {:?}",
            NODE_FLOOR.0,
            NODE_FLOOR.1,
            node_version.trim()
        ));
    }
    step_verdict(problems)
}

#[cfg(test)]
#[path = "workflow_tests.rs"]
mod tests;
